var t=`1358-ajiaco-santafereno`;var a=`world-1358`;var n=`CO`;var s=`south-america`;var o=4;var r=111;var l={en:`Ajiaco Santafereño`,ua:`Ахіако сантаференьйо`};var g={en:`Ajiaco Santafereño is a dish from Colombia featuring chicken breast, yellow onion, garlic, potato. This home-sized recipe records each ingredient at the step where it is used. Guascas, the distinctive herb in Bogotá ajiaco, is absent from the catalog; cilantro is not equivalent.`,ua:`Ахіако сантаференьйо, страва кухні країни Колумбія з такими основними складниками: куряча грудка, жовта цибуля, часник, картопля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Гуаскас, характерної трави для боготинського ахіако, немає в каталозі; кінза не є рівноцінною заміною.`};var c=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 75 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 75 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:75,i:[[`chicken-breast`,740,`g`],[`chicken-stock`,1300,`ml`],[`yellow-onion`,170,`g`],[`garlic`,5,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 28 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 28 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:28,i:[[`potato`,660,`g`],[`sweet-corn`,2,`pcs`],[`cilantro`,65,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,3,`g`]]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`capers`,75,`g`],[`heavy-cream`,180,`ml`],[`avocado`,2,`pcs`]]}];var d={slug:t,id:a,country:`CO`,region:s,servings:4,minutes:111,title:l,text:g,steps:c};export{n as country,d as default,a as id,r as minutes,s as region,o as servings,t as slug,c as steps,g as text,l as title};